#include <stdio.h>
#include <string.h>

#define MOD 1000000007LL
#define MAXN 2000005

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    static char S[MAXN];
    long long K;
    if (scanf("%s %lld", S, &K) != 2) return 0;

    long long N = (long long)strlen(S);
    long long M = N + K;

    static long long fact[MAXN], invfact[MAXN], pow25[MAXN], pow26[MAXN];

    fact[0] = 1;
    for (long long i = 1; i <= M; i++) fact[i] = fact[i - 1] * i % MOD;

    invfact[M] = modpow(fact[M], MOD - 2);
    for (long long i = M; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    pow25[0] = pow26[0] = 1;
    for (long long i = 1; i <= K; i++) {
        pow25[i] = pow25[i - 1] * 25 % MOD;
        pow26[i] = pow26[i - 1] * 26 % MOD;
    }

    long long ans = 0;

    for (long long i = N; i <= N + K; i++) {
        long long add_after = i - N;
        long long remain = N + K - i;

        long long comb = fact[i - 1] * invfact[N - 1] % MOD * invfact[add_after] % MOD;
        long long ways = comb * pow25[add_after] % MOD * pow26[remain] % MOD;
        ans += ways;
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans % MOD);
    return 0;
}

