public class Main {
    static final int MOD = 1_000_000_007;

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * a) % MOD;
            a = (a * a) % MOD;
            e >>= 1;
        }
        return res;
    }

    static long[] fact, invFact;

    static void precomputeFactorials(int n) {
        fact = new long[n + 1];
        invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = (fact[i - 1] * i) % MOD;
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n - 1; i >= 0; i--) invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
    }

    static long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String S = sc.next();
        int K = sc.nextInt();
        int N = S.length();
        precomputeFactorials(N + K);
        long ans = comb(N + K, N) * modPow(26, K) % MOD;
        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String S = fs.next();
        int K = fs.nextInt();

        int n = S.length();
        int m = n + K;

        // dp[i][j]:
        // considering first i characters of the final string,
        // matched j characters of S as a subsequence,
        // and never completed all of S before position i.
        long[][] dp = new long[m + 1][n + 1];
        dp[0][0] = 1;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j <= n; j++) {
                long cur = dp[i][j];
                if (cur == 0) continue;

                if (j < n) {
                    // Put the next needed character of S
                    dp[i + 1][j + 1] = (dp[i + 1][j + 1] + cur) % MOD;

                    // Put any other character
                    dp[i + 1][j] = (dp[i + 1][j] + cur * 25) % MOD;
                } else {
                    // Once all of S is matched exactly at the end, no restriction anymore
                    dp[i + 1][j] = (dp[i + 1][j] + cur * 26) % MOD;
                }
            }
        }

        // We need strings obtainable by inserting K letters into S.
        // This is equivalent to counting strings T of length n+K such that S is a subsequence of T.
        // But if S appears multiple times as a subsequence, we must count T only once.
        //
        // The DP above counts each string exactly once by tracking the earliest completion
        // of matching S as a subsequence.
        //
        // Therefore answer is sum of states where all S is matched by the end.
        long ans = dp[m][n] % MOD;
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

