const int MOD = 1e9+7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    int K;
    cin >> S >> K;
    int n = S.size();
    int L = n + K;

    vector<vector<int>> dp(L+1, vector<int>(n+1, 0));
    dp[0][0] = 1;

    for (int i = 0; i < L; i++) {
        for (int j = 0; j <= n; j++) {
            if (dp[i][j] == 0) continue;
            if (j < n) {
                // match next char
                dp[i+1][j+1] = (dp[i+1][j+1] + dp[i][j]) % MOD;
                // any other char (25 choices)
                dp[i+1][j] = (dp[i+1][j] + (int64)dp[i][j] * 25) % MOD;
            } else {
                // already matched all, any char (26 choices)
                dp[i+1][j] = (dp[i+1][j] + (int64)dp[i][j] * 26) % MOD;
            }
        }
    }

    cout << dp[L][n] % MOD << "\n";
    return 0;
}

