#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

// Fast exponentiation
long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    long long K;
    cin >> S >> K;

    int N = (int)S.size();

    // We count all strings T obtainable after exactly K insertions.
    // Equivalent known formula:
    // answer = sum_{i=0}^{K} C(N-1+i, N-1) * 25^i * 26^(K-i)
    //
    // We compute it in O(K) using recurrence on combinations.

    long long ans = 0;

    // comb = C(N-1+0, N-1) = 1
    long long comb = 1;

    // Start with 26^K
    long long p26 = modpow(26, K);
    long long inv26 = modpow(26, MOD - 2);

    long long p25 = 1;

    // Precompute modular inverses up to N+K if needed for recurrence denominator
    vector<long long> inv(N + K + 1);
    inv[1] = 1;
    for (long long i = 2; i <= N + K; i++) {
        inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
    }

    for (long long i = 0; i <= K; i++) {
        ans = (ans + comb * p25 % MOD * p26) % MOD;

        // Move to next i:
        // C(N-1+(i+1), N-1) = C(N-1+i, N-1) * (N+i)/(i+1)
        if (i != K) {
            comb = comb * (N + i) % MOD * inv[i + 1] % MOD;
            p25 = p25 * 25 % MOD;
            p26 = p26 * inv26 % MOD;
        }
    }

    cout << ans % MOD << '\n';
    return 0;
}

